update public.products p
   set image_url = ph.image_url
  from ph
 where p.source = 'admin'
   and p.image_url is null
   and p.name_norm = public.norm_name(ph.name)
   and coalesce(p.category_slug, '') = ph.category_slug;

select count(*) filter (where source = 'admin' and image_url is not null)
         as "справочных с фото",
       count(*) filter (where source = 'admin' and image_url is null)
         as "справочных без фото"
  from public.products;
